## Why This Is Asked
Real-world rendering challenges with large lists and bursty updates.

## Key Concepts
- FlatList virtualization
- Memoization and stable keys
- Batched updates and interval flushing
- Native event emitters and bridging

## Code Example
```javascript
import { useEffect, useRef, useState } from 'react';
import { NativeEventEmitter, NativeModules } from 'react-native';

export function useLiveList(channel) {
  const [updates, setUpdates] = useState([]);
  const buf = useRef([]);

  useEffect(() => {
    const emitter = new NativeEventEmitter(NativeModules[channel]);
    const subscription = emitter.addListener('dataUpdate', (data) => {
      buf.current.push(data);
    });

    const flushInterval = setInterval(() => {
      if (buf.current.length > 0) {
        setUpdates(prev => [...prev, ...buf.current]);
        buf.current = [];
      }
    }, 16); // ~60fps

    return () => {
      subscription.remove();
      clearInterval(flushInterval);
    };
  }, [channel]);

  return updates;
}

// Usage in component
function LiveDashboard() {
  const data = useLiveList('LiveDataSource');

  const renderItem = useCallback(({ item }) => (
    <MemoizedListItem item={item} />
  ), []);

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      getItemLayout={(data, index) => ({ length: 80, offset: 80 * index, index })}
      initialNumToRender={10}
      maxToRenderPerBatch={5}
      windowSize={10}
      removeClippedSubviews
      keyExtractor={(item, index) => `item-${item.id || index}`}
    />
  );
}
```

## Why This Is Asked
Tests ability to design a resilient, beginner-friendly offline-first feature using core RN APIs, with practicalCaching and reconnect handling.

## Key Concepts
- AsyncStorage for caching
- NetInfo for connectivity events
- FlatList with numColumns=2 for a grid
- Simple retry/backoff and error handling
- Stale data strategy (timestamp checks)

## Code Example
```javascript
import {useEffect, useState, useCallback} from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

export function useImageList(endpoint) {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async (force = false) => {
    if (!force) {
      const cached = await AsyncStorage.getItem('images_cache');
      if (cached) {
        setImages(JSON.parse(cached));
        setLoading(false);
        return;
      }
    }
    try {
      const res = await fetch(endpoint);
      const data = await res.json();
      setImages(data);
      await AsyncStorage.setItem('images_cache', JSON.stringify(data));
      await AsyncStorage.setItem('images_cache_ts', Date.now().toString());
      setError(null);
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  useEffect(() => {
    load();
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) load(true);
    });
    return () => unsubscribe();
  }, [load]);

  return { images, loading, error, retry: () => load(true) };
}
```

